{"l":8420,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'I'd rather you ___ my phone without asking.'","o":["don't use","not use","didn't use","won't use"],"a":"didn't use","r":"Efter 'I'd rather you' bruger man datid, selv om det handler om nu eller fremtiden."},
{"l":8460,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'The island ___ to be home to a rare type of frog.'","o":["says","is saying","has said","is said"],"a":"is said","r":"'Is said to be' er en passiv konstruktion: man siger, at øen er hjem for frøen."},
{"l":8480,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Freya spent her pocket money on seeds and spent every evening watering them. By August, the family hardly needed to buy vegetables.' Hvad viser teksten om Freya?","o":["Hun er tålmodig og flittig","Hun er doven og glemsom","Hun kan ikke lide grøntsager","Hun købte mange grøntsager"],"a":"Hun er tålmodig og flittig","r":"Hun vandede hver aften i månedsvis, og familien fik grøntsager nok. Det kræver tålmodighed og flid."},
{"l":8500,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'grundigt' på engelsk i 'Read the contract ___ before signing'?","o":["roughly","thoroughly","briefly","loudly"],"a":"thoroughly","r":"'Thoroughly' betyder grundigt."},
{"l":8500,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'overvældende' på engelsk i 'an ___ majority'?","o":["overlapping","increasing","overwhelming","outstanding"],"a":"overwhelming","r":"'Overwhelming' = overvældende."},
{"l":8500,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'ulempe' på engelsk?","o":["feedback","backdrop","payback","drawback"],"a":"drawback","r":"'Drawback' betyder en ulempe."},
{"l":8520,"g":8,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'jovial' i 'a jovial host'?","o":["cheerful","nervous","strict","wealthy"],"a":"cheerful","r":"'Jovial' betyder munter og hyggelig, altså 'cheerful'."},
{"l":8530,"g":8,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'resolute' i 'a resolute leader'?","o":["nervous","determined","popular","elderly"],"a":"determined","r":"'Resolute' betyder beslutsom og målrettet, altså 'determined'."},
{"l":8550,"g":8,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'The school canteen has proudly announced its new healthy menu, which, as far as anyone can tell, consists of the old menu with a side salad.' Hvad mener skribenten?","o":["At den nye menu er meget sundere","At kantinen er blevet lukket","At menuen stort set er den samme","At salaten er det eneste problem"],"a":"At menuen stort set er den samme","r":"Skribenten er ironisk: den 'nye' menu er bare den gamle med en salat ved siden af."},
{"l":8570,"g":8,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: '___ any further information, please contact the school office.'","o":["You should need","Should need you","If you needing","Should you need"],"a":"Should you need","r":"'Should you need' er en formel, inverteret betingelse (= If you need). De andre former er grammatisk forkerte."},
{"l":8590,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad betyder 'by and large' i 'By and large, the school trip was a success.'?","o":["stort set","til sidst","overraskende nok","desværre"],"a":"stort set","r":"'By and large' betyder i det store og hele eller stort set."},
{"l":8610,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man høfligt beder nogen om at vente et øjeblik, mens man finder noget?","o":["Carry with me a moment.","Bear with me a moment.","Wait on me a moment.","Hold me a moment."],"a":"Bear with me a moment.","r":"'Bear with me' er en høflig måde at bede om lidt tålmodighed på. 'Wait on me' betyder at betjene mig."},
{"l":8640,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'bewildered' i 'a bewildered tourist'?","o":["delighted","wealthy","confused","lonely"],"a":"confused","r":"'Bewildered' betyder forvirret og rådvild, altså 'confused'."},
{"l":8660,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'conceal' i 'conceal the truth'?","o":["ignore","bend","accept","reveal"],"a":"reveal","r":"'Conceal' betyder at skjule, så det modsatte er 'reveal' (afsløre)."},
{"l":8690,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'sparse' i 'sparse vegetation'?","o":["dense","dry","green","tall"],"a":"dense","r":"'Sparse' betyder spredt eller tynd, så det modsatte er 'dense' (tæt)."},
{"l":8710,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Ella insists she is not a morning person, yet she is always the first to arrive at swimming practice at six.' Hvad er det overraskende ved Ella?","o":["At hun ikke kan lide at svømme længere","At hun opfører sig modsat det, hun siger","At hun ofte kommer for sent til træning","At hun hellere vil træne om aftenen"],"a":"At hun opfører sig modsat det, hun siger","r":"'Yet' viser en modsætning: hun siger, hun ikke er et morgenmenneske, men hun kommer først klokken seks."},
{"l":8730,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Lucas said he would think about joining the chess club, which, from Lucas, usually means no.' Hvad antyder teksten?","o":["At Lucas elsker at spille skak","At Lucas skal tænke i lang tid","At Lucas nok ikke melder sig ind","At Lucas allerede er medlem"],"a":"At Lucas nok ikke melder sig ind","r":"'Which, from Lucas, usually means no' viser, at hans 'I will think about it' plejer at være et høfligt nej."},
{"l":8760,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hedder 'utrættelige' på engelsk i 'Thanks to her ___ efforts, the library finally got new computers.'?","o":["careless","harmless","priceless","tireless"],"a":"tireless","r":"'Tireless' betyder utrættelig. 'Priceless' betyder uvurderlig, og 'careless' betyder skødesløs."},
{"l":8800,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Supposing you ___ a million kroner, what would you do with it?'","o":["found","will find","find","have found"],"a":"found","r":"'Supposing' fungerer som 'if' i en type 2-betingelse, så man bruger datid ('found') sammen med 'would'."},
{"l":8820,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'My brother speaks three languages fluently, and so ___ my cousin.'","o":["is","does","can","has"],"a":"does","r":"Efter 'and so' gentages hjælpeverbet; 'speaks' er nutid uden hjælpeverbum, så man bruger 'does': 'so does my cousin'."},
{"l":8850,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'The results appear to suggest that the new medicine may reduce symptoms in some patients, although further research is needed.' Hvor sikre er forskerne på resultatet?","o":["Helt sikre på, at medicinen virker","Uinteresserede i resultaterne","Forsigtige og ikke helt sikre","Sikre på, at medicinen er farlig"],"a":"Forsigtige og ikke helt sikre","r":"Ord som 'appear to suggest', 'may' og 'some' er forsigtige formuleringer (hedging), og der kræves mere forskning."},
{"l":8900,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'If only I ___ my sister's advice before the trip!'","o":["took","have taken","would take","had taken"],"a":"had taken","r":"'If only' om fortiden kræver førnutid: 'had taken'. Det udtrykker fortrydelse."},
{"l":8920,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Preliminary data indicate a possible link between screen time and poor sleep, but researchers caution against drawing firm conclusions.' Hvad mener forskerne?","o":["At sammenhængen endnu ikke er bevist","At skærme bestemt ødelægger søvnen","At der slet ingen sammenhæng er","At man skal sove med telefonen"],"a":"At sammenhængen endnu ikke er bevist","r":"'Preliminary', 'possible link' og 'caution against drawing firm conclusions' viser, at intet er bevist endnu."},
{"l":8950,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'He talks as if he ___ the whole city, but he only moved here last month.'","o":["has known","knew","will know","had been knowing"],"a":"knew","r":"Efter 'as if' bruges datid om noget, der ikke er sandt: han kender ikke byen, men taler som om."},
{"l":8996,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'allestedsnærværende' på engelsk?","o":["ambiguous","ridiculous","ubiquitous","superfluous"],"a":"ubiquitous","r":"'Ubiquitous' betyder, at noget findes overalt."},
{"l":9000,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'We regret to inform you that your application has not been successful on this occasion. We wish you every success in the future.' Hvilken tone har teksten?","o":["Vred og anklagende","Spøgefuld og personlig","Begejstret og glad","Høflig og formel"],"a":"Høflig og formel","r":"'We regret to inform you' og 'We wish you every success' er faste, høflige og formelle vendinger i et afslag."},
{"l":9008,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'omhyggelig' på engelsk?","o":["meticulous","ridiculous","miraculous","ambitious"],"a":"meticulous","r":"'Meticulous' betyder meget omhyggelig."},
{"l":9019,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'tvetydig' på engelsk i 'The instructions were ___, so nobody knew what to do'?","o":["ambitious","ambiguous","obvious","generous"],"a":"ambiguous","r":"'Ambiguous' betyder, at noget kan forstås på flere måder."},
{"l":9028,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'splittet / tvivlrådig' på engelsk?","o":["equivalent","ambitious","ambivalent","benevolent"],"a":"ambivalent","r":"'Ambivalent' betyder at have blandede følelser."},
{"l":9040,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'Scientists hope the new telescope will ___ light on how galaxies form.'","o":["put","bring","take","shed"],"a":"shed","r":"Den faste forbindelse er 'shed light on' (kaste lys over). De andre verber danner ikke et udtryk med 'light on'."},
{"l":9043,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'partiskhed / skævvridning' på engelsk i 'The article showed a clear political ___'?","o":["bias","basis","shift","debate"],"a":"bias","r":"'Bias' = forudindtagethed."},
{"l":9052,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'medgørlig / følger reglerne' på engelsk?","o":["complacent","compliant","competent","compatible"],"a":"compliant","r":"'Compliant' betyder, at man følger regler eller krav."},
{"l":9060,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad betyder 'a tall order' i 'Finishing the whole project by Monday is a tall order.'?","o":["en stor bestilling","en høj bygning","en svær opgave","en klar besked"],"a":"en svær opgave","r":"'A tall order' er en opgave, der er meget svær eller næsten umulig at klare."},
{"l":9066,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'upartisk' på engelsk?","o":["impatient","imperial","immaterial","impartial"],"a":"impartial","r":"'Impartial' = upartisk."},
{"l":9077,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'sammenhængende' på engelsk?","o":["coherent","inherent","competent","decent"],"a":"coherent","r":"'Coherent' = sammenhængende."},
{"l":9080,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Thanks so much for lending me your bike yesterday! I promise the scratch on the frame was already there. Mostly.' Hvad antyder det sidste ord?","o":["At cyklen var helt ny og uden ridser","At skribenten nok selv lavede noget af ridsen","At skribenten gerne vil købe cyklen","At ridsen allerede var blevet repareret"],"a":"At skribenten nok selv lavede noget af ridsen","r":"Ordet 'Mostly' tilføjet til sidst indrømmer halvt, at skribenten selv har lavet en del af ridsen."},
{"l":9089,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'sparsom / ringe' på engelsk?","o":["eager","meek","meagre","major"],"a":"meagre","r":"'Meagre' = sparsom (fx løn)."},
{"l":9101,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'apatisk / sløv' på engelsk?","o":["pathetic","sympathetic","athletic","apathetic"],"a":"apathetic","r":"'Apathetic' = uden interesse."},
{"l":9110,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man høfligt vil sige nej til en ekstra opgave, fordi man har for travlt?","o":["I'm afraid I've got too much on right now.","I'm afraid I have too much on my head.","I'm sorry, but I am not having time.","I'm afraid I'm busy like a bee now."],"a":"I'm afraid I've got too much on right now.","r":"'I've got too much on' betyder, at man har for travlt. 'Not having time' og 'busy like a bee' er ikke korrekt engelsk."},
{"l":9112,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'streng / nøgtern' på engelsk?","o":["astute","austere","obscure","sincere"],"a":"austere","r":"'Austere' = stram, uden luksus."},
{"l":9124,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'sparepolitik / stramninger' på engelsk?","o":["authority","adversity","austerity","prosperity"],"a":"austerity","r":"'Austerity' = nedskæringer i offentlige udgifter."},
{"l":9136,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'ildevarslende' på engelsk?","o":["anonymous","luminous","onerous","ominous"],"a":"ominous","r":"'Ominous' = ildevarslende."},
{"l":9140,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Not until the bell rang ___ that he had left his homework at home.'","o":["did Jonas realise","Jonas realised","realised Jonas","had Jonas realise"],"a":"did Jonas realise","r":"'Not until ...' først i sætningen kræver inversion i hovedsætningen: 'did Jonas realise'."},
{"l":9147,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'lovende / gunstig' på engelsk?","o":["suspicious","auspicious","ambitious","malicious"],"a":"auspicious","r":"'Auspicious' = lovende."},
{"l":9159,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'besværlig / slidsom' på engelsk?","o":["ardent","dubious","arduous","hazardous"],"a":"arduous","r":"'Arduous' = krævende."},
{"l":9160,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'By the time the rescue team reached the summit, the climbers had already begun their descent. The helicopter, it turned out, had not been needed after all.' Hvad kan man udlede af teksten?","o":["At helikopteren styrtede ned","At redningsholdet aldrig kom frem","At klatrerne var kommet til skade","At klatrerne klarede sig selv ned"],"a":"At klatrerne klarede sig selv ned","r":"Klatrerne var allerede på vej ned, og helikopteren var ikke nødvendig, så de klarede sig uden hjælp."},
{"l":9170,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'ustabil / flygtig' på engelsk?","o":["volatile","versatile","juvenile","futile"],"a":"volatile","r":"'Volatile' = ustabil."},
{"l":9180,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'She ___ have seen me at the party, because I wasn't there.'","o":["mustn't","can't","shouldn't","needn't"],"a":"can't","r":"'Can't have' + kort tillægsform udtrykker, at noget er umuligt i fortiden. 'Mustn't have' bruges ikke om sikre slutninger på britisk engelsk."},
{"l":9186,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'fremkalde (et svar)' på engelsk?","o":["illicit","exhibit","elicit","enlist"],"a":"elicit","r":"'Elicit' betyder at lokke frem, fx en reaktion. 'Illicit' betyder ulovlig."},
{"l":9198,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'ulovlig' på engelsk?","o":["implicit","explicit","idyllic","illicit"],"a":"illicit","r":"'Illicit' betyder ulovlig."},
{"l":9205,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'svær at fange / undvigende' på engelsk?","o":["elusive","exclusive","effusive","abusive"],"a":"elusive","r":"'Elusive' = svær at få fat på."},
{"l":9210,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'inquisitive' i 'an inquisitive child'?","o":["polite","curious","anxious","clumsy"],"a":"curious","r":"'Inquisitive' betyder videbegærlig og nysgerrig, altså 'curious'."},
{"l":9223,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'udtrykkelig / tydelig' på engelsk?","o":["implicit","illicit","explicit","exquisite"],"a":"explicit","r":"'Explicit' betyder klart udtrykt."},
{"l":9230,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Should the weather ___, the picnic will be moved indoors.'","o":["worsens","worsened","to worsen","worsen"],"a":"worsen","r":"'Should + subjekt + grundform' er en inverteret betingelse (= If the weather worsens), så verbet står i grundform."},
{"l":9240,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man i et formelt møde vil bede nogen om at gentage det sidste, de sagde?","o":["Sorry, could you repeat that last point?","Huh, what was that you just said there?","Repeat the last thing you said again.","Could you say me that last point again?"],"a":"Sorry, could you repeat that last point?","r":"'Sorry, could you repeat that last point?' er høfligt og korrekt. 'Say me' er forkert, og 'Huh' og en bydeform er for uformelle."},
{"l":9252,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'flittig' på engelsk?","o":["delinquent","diligent","indulgent","intelligent"],"a":"diligent","r":"'Diligent' betyder flittig og omhyggelig."},
{"l":9260,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'The window is broken, so someone ___ have kicked a ball through it.'","o":["should","ought","must","would"],"a":"must","r":"'Must have' + kort tillægsform udtrykker en sikker slutning om fortiden. 'Ought' kræver 'to', og 'should have' betyder burde have."},
{"l":9271,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'granske' på engelsk?","o":["summarise","sanitise","stigmatise","scrutinise"],"a":"scrutinise","r":"'Scrutinise' betyder at undersøge nøje."},
{"l":9280,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'If he had saved his money, he ___ a new bike now.'","o":["could afford","could have afforded","would have afford","can afford"],"a":"could afford","r":"Blandet betingelse: fortiden ('had saved') påvirker nutiden ('now'), så hovedsætningen er 'could afford'."},
{"l":9290,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'When Oliver finally opened his report card, he went very quiet and then asked whether we could talk about it after dinner.' Hvad kan man udlede af teksten?","o":["At han var meget sulten lige nu","At karaktererne nok var skuffende","At han ikke kunne finde kortet","At han havde vundet en stor pris"],"a":"At karaktererne nok var skuffende","r":"Han bliver stille og vil udsætte samtalen, hvilket antyder, at indholdet ikke var godt."},
{"l":9298,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'vaskemiddel' på engelsk?","o":["deterrent","deodorant","detergent","decanter"],"a":"detergent","r":"'Detergent' = vaskemiddel."},
{"l":9310,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'afskrække' på engelsk?","o":["defer","detect","decay","deter"],"a":"deter","r":"'Deter' = afskrække."},
{"l":9310,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Can you join us for lunch? I'd love ___, but I have a dentist appointment.'","o":["to","it","so","that"],"a":"to","r":"Ellipse: 'I'd love to' står for 'I'd love to join you'. 'To' alene erstatter resten af infinitiven."},
{"l":9321,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'forståelig' på engelsk?","o":["comprehensive","comprehensible","compatible","contemptible"],"a":"comprehensible","r":"'Comprehensible' betyder forståelig."},
{"l":9332,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'fordømme' på engelsk?","o":["condone","contend","condemn","condense"],"a":"condemn","r":"'Condemn' betyder fordømme."},
{"l":9340,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man fortryder noget sårende, man lige har sagt, og trækker det tilbage?","o":["I take that off.","I give that back.","I put that down.","I take that back."],"a":"I take that back.","r":"'I take that back' betyder, at man trækker sine ord tilbage. De andre er ikke faste udtryk med den betydning."},
{"l":9345,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'stige kraftigt / svæve' på engelsk?","o":["soar","sow","soak","sear"],"a":"soar","r":"'Soar' = stige kraftigt (fx priser)."},
{"l":9356,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'styrtdykke' på engelsk?","o":["pummel","plummet","plunder","flutter"],"a":"plummet","r":"'Plummet' = falde brat."},
{"l":9369,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'diskret' på engelsk?","o":["discrete","distinct","discreet","devout"],"a":"discreet","r":"'Discreet' betyder diskret. 'Discrete' betyder adskilt."},
{"l":9380,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'tilbageslag' på engelsk?","o":["feedback","backlog","outset","setback"],"a":"setback","r":"'Setback' = tilbageslag."},
{"l":9391,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'gentage' på engelsk?","o":["reiterate","retaliate","reinstate","irritate"],"a":"reiterate","r":"'Reiterate' = gentage, understrege igen."},
{"l":9400,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'He ___ to have been a brilliant footballer when he was young.'","o":["says","is said","said","is saying"],"a":"is said","r":"'He is said to have been' er en passiv refererende konstruktion: man siger om ham, at han var en dygtig spiller."},
{"l":9420,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'I would love to come to your party on Saturday. Unfortunately, I have promised to help my aunt move house that day.' Hvad er formålet med teksten?","o":["At sige ja til at komme til festen","At bede om hjælp til en flytning","At takke høfligt nej til festen","At invitere vennen med til tanten"],"a":"At takke høfligt nej til festen","r":"'I would love to ... Unfortunately' er en høflig måde at sige nej på."},
{"l":9450,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'The reason ___ I am late is that the bus broke down.'","o":["because","for","what","why"],"a":"why","r":"Konstruktionen er 'The reason why ... is that ...'. 'The reason because' er forkert."},
{"l":9480,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'dormant' i 'a dormant volcano'?","o":["active","extinct","distant","enormous"],"a":"active","r":"'Dormant' betyder slumrende eller hvilende, så det modsatte er 'active'. En 'extinct' vulkan er helt udslukt."},
{"l":9520,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Having spent the entire weekend revising, Sara was somewhat surprised, and more than a little annoyed, to learn that the test had been postponed.' Hvordan har Sara det?","o":["Lettet og meget glad","Overrasket og ret irriteret","Helt ligeglad med det","Nervøs og bange"],"a":"Overrasket og ret irriteret","r":"'More than a little annoyed' er en underdrivelse, der betyder ret irriteret; hun havde jo læst hele weekenden."},
{"l":9550,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'diminutive' i 'a diminutive figure'?","o":["distant","elegant","tiny","gloomy"],"a":"tiny","r":"'Diminutive' betyder meget lille, altså 'tiny'."},
{"l":9570,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'The author never tells us directly that Anna is lonely; instead, we see her setting the table for two every evening, although she lives alone.' Hvordan viser forfatteren Annas ensomhed?","o":["Gennem en direkte beskrivelse","Gennem hendes breve","Gennem en samtale med en ven","Gennem det, hun gør"],"a":"Gennem det, hun gør","r":"Forfatteren viser ensomheden indirekte gennem Annas handlinger: hun dækker bord til to, selv om hun bor alene."},
{"l":9590,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Historians once assumed that the Vikings never reached North America. Excavations in Newfoundland, however, proved them wrong.' Hvad viser teksten?","o":["At en tidligere antagelse blev modbevist","At vikingerne aldrig kom til Amerika","At historikere altid har haft ret","At udgravningerne intet fandt"],"a":"At en tidligere antagelse blev modbevist","r":"'Once assumed' og 'proved them wrong' viser, at en gammel antagelse blev modbevist af udgravningerne."},
{"l":9610,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Few would dispute that the bridge is an engineering marvel; whether it was worth three times its original budget is another matter.' Hvad mener skribenten?","o":["Broen er grim, men den var heldigvis billig","Broen er imponerende, men prisen kan diskuteres","Broen blev bygget hurtigere end planlagt","Ingen mener, at broen er særlig imponerende"],"a":"Broen er imponerende, men prisen kan diskuteres","r":"'Few would dispute' betyder, at næsten alle er enige om, at broen er imponerende, mens 'another matter' sår tvivl om prisen."},
{"l":9640,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hedder 'tilbageholdende' på engelsk i 'She was ___ about her plans, so nobody knew where she was going.'?","o":["redundant","repetitive","reticent","resentful"],"a":"reticent","r":"'Reticent' betyder tilbageholdende og fåmælt om sig selv. 'Resentful' betyder bitter, og 'redundant' betyder overflødig."},
{"l":9660,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'The school choir ___ perform at the royal palace next month.'","o":["is about","is due","is used","is to"],"a":"is to","r":"'Be to + grundform' bruges formelt om noget, der er planlagt. 'Is about' og 'is due' kræver 'to' efter sig."},
{"l":9690,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'The decision to close the pool was met with widespread ___.'","o":["dismay","dismiss","display","disguise"],"a":"dismay","r":"'Dismay' betyder bestyrtelse eller skuffelse. De andre ord ligner, men giver ikke mening her."},
{"l":9710,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'The new shopping centre, we were told, would breathe life into the town. Five years on, half of its units stand empty.' Hvad antyder skribenten?","o":["At byen har for mange butikker","At løftet ikke er blevet indfriet","At centret blev bygget for sent","At centret er en kæmpe succes"],"a":"At løftet ikke er blevet indfriet","r":"'We were told' viser afstand til løftet, og de tomme butikker viser, at centret ikke gav byen nyt liv."},
{"l":9740,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'at stjæle opmærksomheden' på engelsk?","o":["to run the show","to steal a glance","to steal the show","to save the day"],"a":"to steal the show","r":"'to steal the show' betyder at stjæle opmærksomheden. Udtrykket betyder at være den, alle lægger mærke til."},
{"l":9760,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'The proposal met with fierce ___ from local residents.'","o":["competition","ambition","condition","opposition"],"a":"opposition","r":"'Meet with fierce opposition' betyder at møde hård modstand. De andre navneord giver ikke mening her."},
{"l":9790,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Such ___ the demand for tickets that the concert sold out in minutes.'","o":["was","did","had","were"],"a":"was","r":"'Such was ... that ...' er en inverteret, fremhævende konstruktion; 'the demand' er ental, så verbet er 'was'."},
{"l":9810,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Although the team lost the final, the coach described the season as the most rewarding of her career.' Hvad kan man udlede om træneren?","o":["At hun var meget skuffet over sæsonen","At hun lægger vægt på mere end sejre","At holdet vandt finalen til sidst","At hun stopper efter denne sæson"],"a":"At hun lægger vægt på mere end sejre","r":"'Although' viser, at hun er glad for sæsonen trods nederlaget; hun værdsætter altså andet end at vinde."},
{"l":9840,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man vil sige, at to ting er helt forskellige og ikke kan sammenlignes?","o":["It's like comparing cats and mice.","They are like two drops of water.","It's like comparing apples and oranges.","It's like apples and pears together."],"a":"It's like comparing apples and oranges.","r":"'Comparing apples and oranges' betyder at sammenligne ting, der ikke kan sammenlignes. 'Like two drops of water' ville betyde, at de er ens."},
{"l":9870,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Our class representative, never one to miss an opportunity to speak, gave a forty-minute answer to a yes-or-no question.' Hvad antyder teksten om klasserepræsentanten?","o":["At personen er meget genert","At personen svarede kort og præcist","At personen ikke forstod spørgsmålet","At personen elsker at tale længe"],"a":"At personen elsker at tale længe","r":"'Never one to miss an opportunity to speak' og et svar på 40 minutter til et ja-nej-spørgsmål viser ironisk, at personen taler meget."},
{"l":9890,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad betyder 'a rule of thumb' i 'As a rule of thumb, you should drink water before you feel thirsty.'?","o":["en tommelfingerregel","en streng lov","en sjælden undtagelse","en gammel overtro"],"a":"en tommelfingerregel","r":"'A rule of thumb' er en tommelfingerregel, altså en praktisk hovedregel."},
{"l":9930,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'fragile' i 'a fragile vase'?","o":["valuable","sturdy","empty","ancient"],"a":"sturdy","r":"'Fragile' betyder skrøbelig, så det modsatte er 'sturdy' (robust, solid)."},
{"l":9960,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Our neighbour describes his garden as low-maintenance, which in practice means he has paved over most of it.' Hvilken tone har skribenten?","o":["Dybt beundrende","Helt neutral","Let spydig","Meget vred"],"a":"Let spydig","r":"'Which in practice means' afslører med et lille stik, at haven er nem at passe, fordi den mest er belagt med fliser."},
{"l":9980,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'In theory, the new homework platform saves teachers time. In practice, it has created an entirely new job: explaining how the platform works.' Hvad er skribentens pointe?","o":["At platformen sparer meget tid","At eleverne elsker platformen","At lærerne ikke vil bruge den","At platformen skaber mere arbejde"],"a":"At platformen skaber mere arbejde","r":"Kontrasten 'In theory ... In practice' viser ironisk, at platformen giver lærerne ekstra arbejde i stedet for at spare tid."},
{"l":10000,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'hidtil' på engelsk i 'a ___ unknown species'?","o":["hitherto","thereby","hereafter","otherwise"],"a":"hitherto","r":"'Hitherto' = hidtil."},
{"l":10000,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'utilsigtet' på engelsk?","o":["indefinitely","inadvertently","intermittently","independently"],"a":"inadvertently","r":"'Inadvertently' = uden at mene det."}
]$$::jsonb) AS e
JOIN (VALUES
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('h', 'hverdagsudtryk', 'comprehension', 'conceptual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
